-- ┌───────────────────────────────────────────────────────────────
-- │ attendance_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Attendance v1 (26 Nov 2026)
--  * Office staff can clock in at the office: no project needed. The phone's GPS must be
--    within the office radius (checked here in the database, so the page cannot be bypassed).
--  * Site staff clock in on a project as before (location recorded).
--  * The CEO sets the office location(s) and radius in Attendance → Office location.
--  * Clock-in / clock-out times are the server's time, not the phone's; hours are worked out here.
--  * One attendance record per person per day (India date).
-- Safe to run more than once.

create table if not exists office_locations (
  id          uuid default gen_random_uuid() primary key,
  name        text not null default 'Head office',
  lat         double precision not null check (lat between -90 and 90),
  lng         double precision not null check (lng between -180 and 180),
  radius_m    integer not null default 200 check (radius_m between 30 and 5000),
  active      boolean not null default true,
  created_by  uuid references profiles(id) on delete set null,
  created_at  timestamptz default now(),
  updated_at  timestamptz default now()
);
alter table office_locations enable row level security;
drop policy if exists "staff_read_offices" on office_locations;
create policy "staff_read_offices" on office_locations for select using (is_staff());
drop policy if exists "ceo_manage_offices" on office_locations;
create policy "ceo_manage_offices" on office_locations for all using (is_admin()) with check (is_admin());

alter table attendance add column if not exists work_type text not null default 'site';
alter table attendance drop constraint if exists attendance_work_type_check;
alter table attendance add constraint attendance_work_type_check check (work_type in ('office','site'));
alter table attendance add column if not exists office_location_id uuid references office_locations(id) on delete set null;
alter table attendance add column if not exists clock_in_accuracy_m numeric;
alter table attendance add column if not exists clock_in_distance_m numeric;
alter table attendance add column if not exists clock_out_accuracy_m numeric;
alter table attendance add column if not exists clock_out_distance_m numeric;
alter table attendance add column if not exists clock_out_address text;

-- One record per person per day (skipped with a notice if old duplicate rows exist)
do $$ begin
  create unique index if not exists attendance_one_per_day on attendance (employee_id, date);
exception when unique_violation then
  raise notice 'attendance_one_per_day not created: there are duplicate days to clean up first';
end $$;

-- Distance in metres between two GPS points
create or replace function geo_distance_m(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
returns double precision language sql immutable as $$
  select 2 * 6371000 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)));
$$;

create or replace function attendance_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  ceo     boolean := auth.uid() is null or is_admin();   -- CEO or the server may correct records
  office  office_locations%rowtype;
  dist    double precision;
  slack   double precision;
begin
  if tg_op = 'INSERT' then
    if not ceo then
      new.date           := (now() at time zone 'Asia/Kolkata')::date;
      new.clock_in_time  := now();
      new.clock_out_time := null; new.clock_out_lat := null; new.clock_out_lng := null;
      new.total_hours    := null; new.overtime_hours := 0;
      new.attendance_status := 'present';
      new.is_location_mismatch := false;
    end if;

    if new.work_type = 'office' then
      new.project_id := null;
      if new.clock_in_lat is null or new.clock_in_lng is null then
        raise exception 'Your location is needed to clock in at the office.';
      end if;
      select * into office from office_locations where active
        order by geo_distance_m(lat, lng, new.clock_in_lat::float8, new.clock_in_lng::float8) limit 1;
      if not found then
        raise exception 'The office location has not been set yet. Ask the CEO to set it in Attendance → Office location.';
      end if;
      dist := geo_distance_m(office.lat, office.lng, new.clock_in_lat::float8, new.clock_in_lng::float8);
      new.office_location_id  := office.id;
      new.clock_in_distance_m := round(dist::numeric);
      -- Indoor GPS is rough: allow the reported accuracy on top of the radius, up to 100 m
      slack := least(coalesce(new.clock_in_accuracy_m::float8, 0), 100);
      if dist > office.radius_m + slack and not ceo then
        raise exception 'You are about % m from %. Office clock-in works within % m. Go to the office (or near a window / outside for a better GPS signal) and try again.',
          round(dist::numeric), office.name, office.radius_m;
      end if;
    elsif new.project_id is null and not ceo then
      raise exception 'Choose the project / site you are working at.';
    end if;
    return new;
  end if;

  -- UPDATE
  if not ceo then
    if old.clock_out_time is not null then
      raise exception 'You have already clocked out today.';
    end if;
    -- Staff may only add their clock-out; everything about the clock-in stays as recorded
    new.employee_id := old.employee_id; new.date := old.date; new.work_type := old.work_type;
    new.project_id := old.project_id; new.office_location_id := old.office_location_id;
    new.clock_in_time := old.clock_in_time; new.clock_in_lat := old.clock_in_lat; new.clock_in_lng := old.clock_in_lng;
    new.clock_in_address := old.clock_in_address; new.clock_in_accuracy_m := old.clock_in_accuracy_m;
    new.clock_in_distance_m := old.clock_in_distance_m; new.attendance_status := old.attendance_status;
    if new.clock_out_time is not null then new.clock_out_time := now(); end if;
  end if;

  if new.clock_out_time is not null and new.work_type = 'office' and new.clock_out_lat is not null and new.clock_out_lng is not null then
    select * into office from office_locations where id = new.office_location_id;
    if found then
      dist := geo_distance_m(office.lat, office.lng, new.clock_out_lat::float8, new.clock_out_lng::float8);
      new.clock_out_distance_m := round(dist::numeric);
      -- Clock-out is never blocked; leaving from somewhere else is flagged for the CEO
      new.is_location_mismatch := dist > office.radius_m + least(coalesce(new.clock_out_accuracy_m::float8, 0), 100);
    end if;
  end if;

  if new.clock_out_time is not null and new.clock_in_time is not null then
    new.total_hours    := round((extract(epoch from new.clock_out_time - new.clock_in_time) / 3600)::numeric, 2);
    new.overtime_hours := greatest(0, new.total_hours - 8);
  end if;
  return new;
end;$$;

drop trigger if exists trg_attendance_guard on attendance;
create trigger trg_attendance_guard before insert or update on attendance
  for each row execute function attendance_guard();


-- ┌───────────────────────────────────────────────────────────────
-- │ attendance_devices_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Attendance trusted phones v1 (26 Nov 2026)
--  * Each staff member registers ONE mobile phone; the CEO approves it.
--  * Clock-in / clock-out only work from that approved phone, and only from a mobile browser.
--  * Staff can no longer write attendance rows directly: everything goes through
--    attendance_clock_in / attendance_clock_out, which check the phone, then the office GPS rules
--    (attendance_v1.sql) still apply.
--  * The CEO does not clock in or out (manages attendance; can still correct records).
-- The phone keeps a random secret; only its SHA-256 is stored here.
-- Needs attendance_v1.sql first. Safe to run more than once.

create table if not exists trusted_devices (
  id           uuid default gen_random_uuid() primary key,
  employee_id  uuid not null references profiles(id) on delete cascade,
  secret_hash  text not null,
  label        text,
  user_agent   text,
  status       text not null default 'pending' check (status in ('pending','approved','rejected','revoked')),
  created_at   timestamptz default now(),
  decided_by   uuid references profiles(id) on delete set null,
  decided_at   timestamptz,
  last_used_at timestamptz
);
create index if not exists trusted_devices_employee on trusted_devices (employee_id, status);
alter table trusted_devices enable row level security;
drop policy if exists "read_trusted_devices" on trusted_devices;
create policy "read_trusted_devices" on trusted_devices for select using (employee_id = auth.uid() or is_manager());
-- No insert / update / delete policies: only the functions below change this table.

alter table attendance add column if not exists device_id uuid references trusted_devices(id) on delete set null;

-- Staff no longer insert or edit attendance directly (the CEO's correction policy stays)
drop policy if exists "Employee clock in/out" on attendance;
drop policy if exists "Employee update own" on attendance;

create or replace function _sha256_hex(t text) returns text language sql immutable as $$
  select encode(sha256(convert_to(t, 'UTF8')), 'hex');
$$;

-- Browser of the current request (PostgREST passes the request headers)
create or replace function _request_is_mobile() returns boolean language plpgsql stable as $$
declare ua text;
begin
  begin ua := coalesce(current_setting('request.headers', true)::json->>'user-agent', '');
  exception when others then ua := ''; end;
  return ua ~* '(android|iphone|ipod|mobile)' and ua !~* '(ipad|tablet)';
end;$$;

create or replace function _request_user_agent() returns text language plpgsql stable as $$
begin
  return left(coalesce(current_setting('request.headers', true)::json->>'user-agent', ''), 400);
exception when others then return ''; end;$$;

-- Staff: ask to make this phone the trusted one
create or replace function register_attendance_device(p_secret text, p_label text)
returns uuid language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); new_id uuid; who text;
begin
  if uid is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if length(coalesce(p_secret, '')) < 32 then raise exception 'Invalid device code.'; end if;
  if not _request_is_mobile() then
    raise exception 'Register from your mobile phone: open the CRM on the phone you will carry to work.';
  end if;
  -- An earlier, still-waiting request is replaced by this one
  update trusted_devices set status = 'rejected', decided_at = now()
    where employee_id = uid and status = 'pending';
  insert into trusted_devices (employee_id, secret_hash, label, user_agent)
    values (uid, _sha256_hex(p_secret), left(coalesce(nullif(trim(p_label), ''), 'Mobile phone'), 80), _request_user_agent())
    returning id into new_id;
  select full_name into who from profiles where id = uid;
  insert into notifications (user_id, type, title, message, link)
    select id, 'attendance', 'Phone waiting for approval',
           coalesce(who, 'A staff member') || ' registered a phone for attendance: ' || coalesce(p_label, 'Mobile phone'), '/staff/attendance'
    from profiles where role = 'admin' and status = 'active';
  return new_id;
end;$$;

-- CEO: approve, reject or revoke. Approving one phone revokes that person's other phones.
create or replace function decide_attendance_device(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
declare d trusted_devices%rowtype;
begin
  if not is_admin() then raise exception 'Only the CEO can approve phones.'; end if;
  if p_status not in ('approved','rejected','revoked') then raise exception 'Unknown status.'; end if;
  select * into d from trusted_devices where id = p_id;
  if not found then raise exception 'Phone not found.'; end if;
  if p_status = 'approved' then
    update trusted_devices set status = 'revoked', decided_by = auth.uid(), decided_at = now()
      where employee_id = d.employee_id and id <> d.id and status in ('approved','pending');
  end if;
  update trusted_devices set status = p_status, decided_by = auth.uid(), decided_at = now() where id = p_id;
  insert into notifications (user_id, type, title, message, link) values (d.employee_id, 'attendance',
    case p_status when 'approved' then 'Your phone is approved for attendance' else 'Your attendance phone was not approved' end,
    case p_status when 'approved' then 'You can now clock in and out from ' || coalesce(d.label, 'your phone') || '.'
         else 'Contact the CEO, or register your phone again.' end,
    '/staff/attendance');
  insert into audit_log (action_by, action_type, target_entity, target_id, description)
    values (auth.uid(), 'attendance_device_' || p_status, 'trusted_devices', p_id,
            'Attendance phone "' || coalesce(d.label, '') || '" ' || p_status);
end;$$;

-- Checks the phone; returns its id (null for the CEO without a phone)
create or replace function _check_attendance_device(p_device uuid, p_secret text)
returns uuid language plpgsql security definer set search_path = public as $$
declare d trusted_devices%rowtype;
begin
  select * into d from trusted_devices
    where id = p_device and employee_id = auth.uid() and status = 'approved'
      and secret_hash = _sha256_hex(coalesce(p_secret, ''));
  if found then
    if not _request_is_mobile() and not is_admin() then
      raise exception 'Attendance can only be marked from your mobile phone.';
    end if;
    update trusted_devices set last_used_at = now() where id = d.id;
    return d.id;
  end if;
  if is_admin() then return null; end if;
  if not _request_is_mobile() then raise exception 'Attendance can only be marked from your mobile phone.'; end if;
  raise exception 'This phone is not your approved attendance phone. Register it on the Attendance page and ask the CEO to approve it.';
end;$$;

create or replace function attendance_clock_in(
  p_device uuid, p_secret text, p_work_type text, p_project uuid,
  p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text)
returns uuid language plpgsql security definer set search_path = public as $$
declare dev uuid; new_id uuid;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  if is_admin() then raise exception 'The CEO does not clock in or out.'; end if;
  dev := _check_attendance_device(p_device, p_secret);
  if exists (select 1 from attendance where employee_id = auth.uid() and date = (now() at time zone 'Asia/Kolkata')::date) then
    raise exception 'You have already clocked in today.';
  end if;
  if p_work_type = 'site' and p_project is not null and not is_manager() and not exists (
    select 1 from project_employees where project_id = p_project and employee_id = auth.uid() and released_date is null) then
    raise exception 'You are not assigned to that project.';
  end if;
  -- attendance_guard (attendance_v1.sql) sets the time and date and checks the office distance
  insert into attendance (employee_id, work_type, project_id, clock_in_lat, clock_in_lng, clock_in_accuracy_m, clock_in_address, device_id)
    values (auth.uid(), case when p_work_type = 'office' then 'office' else 'site' end, p_project,
            p_lat, p_lng, p_accuracy, left(p_address, 500), dev)
    returning id into new_id;
  return new_id;
end;$$;

create or replace function attendance_clock_out(
  p_device uuid, p_secret text, p_lat double precision, p_lng double precision, p_accuracy double precision, p_address text)
returns uuid language plpgsql security definer set search_path = public as $$
declare rec_id uuid;
begin
  if auth.uid() is null or not is_staff() then raise exception 'Please sign in again.'; end if;
  perform _check_attendance_device(p_device, p_secret);
  select id into rec_id from attendance
    where employee_id = auth.uid() and clock_out_time is null and clock_in_time is not null
    order by clock_in_time desc limit 1;
  if rec_id is null then raise exception 'You are not clocked in.'; end if;
  update attendance set clock_out_time = now(), clock_out_lat = p_lat, clock_out_lng = p_lng,
         clock_out_accuracy_m = p_accuracy, clock_out_address = left(p_address, 500)
    where id = rec_id;
  return rec_id;
end;$$;

revoke all on function register_attendance_device(text, text), decide_attendance_device(uuid, text),
  _check_attendance_device(uuid, text),
  attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text),
  attendance_clock_out(uuid, text, double precision, double precision, double precision, text) from public, anon;
grant execute on function register_attendance_device(text, text), decide_attendance_device(uuid, text),
  attendance_clock_in(uuid, text, text, uuid, double precision, double precision, double precision, text),
  attendance_clock_out(uuid, text, double precision, double precision, double precision, text) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ quotation_allocation_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Quotation work allocation v1 (26 Nov 2026)
-- The CEO / admin manager gives each enquiry to up to three people (any staff, or the same person):
--   1. Site visit & customer meeting  → assigned_engineer_id
--   2. Prepares the quotation         → assigned_sales_id
--   3. Follows up with the customer   → follow_up_manager_id
-- and the CEO approves (unchanged). Each person can do their own part, and only that:
--   * the site-visit person records the visit (date, notes, roof / bill details, GPS at the site);
--   * the follow-up person shares the approved quotation, logs calls, marks hot / cold, accepted or lost;
--   * prices stay with the preparer (and the CEO / admin manager).
-- Everyone gets an in-app notification when work is given to them.
-- Safe to run more than once.

alter table quotation_requests add column if not exists site_visit_at      timestamptz;   -- planned date & time
alter table quotation_requests add column if not exists site_visit_done_at timestamptz;
alter table quotation_requests add column if not exists site_visit_notes   text;
alter table quotation_requests add column if not exists site_visit_lat     double precision;
alter table quotation_requests add column if not exists site_visit_lng     double precision;

-- Any of the three people may update the quotation (what they may change is checked below)
drop policy if exists "sales_update_assigned" on quotation_requests;
create policy "sales_update_assigned" on quotation_requests for update
  using (is_staff() and auth.uid() in (assigned_sales_id, assigned_engineer_id, follow_up_manager_id))
  with check (auth.uid() in (assigned_sales_id, assigned_engineer_id, follow_up_manager_id) or is_manager() or can_manage_quotations());

create or replace function quotation_role_guard()
returns trigger language plpgsql set search_path = public as $$
declare
  uid     uuid := auth.uid();
  visitor boolean;
  fu      boolean;
  allowed text[] := array['updated_at', 'next_follow_up_date', 'follow_up_count', 'lead_temperature', 'lead_temperature_note', 'lead_temperature_at'];
  move    text := old.status || '>' || new.status;
begin
  -- Server, CEO, admin manager, delegated staff and the preparer: the main rules (quotation_guard) apply
  if uid is null or is_manager() or can_manage_quotations() or old.assigned_sales_id = uid
     or coalesce(current_setting('greenergy.converting', true), '') = 'on' then
    return new;
  end if;
  visitor := old.assigned_engineer_id = uid;
  fu      := old.follow_up_manager_id = uid;
  if visitor then
    allowed := allowed || array['status', 'site_visit_at', 'site_visit_done_at', 'site_visit_notes', 'site_visit_lat', 'site_visit_lng',
      'address', 'city', 'eb_consumer_number', 'sanctioned_load_kw', 'avg_monthly_units', 'avg_monthly_bill', 'roof_type',
      'available_roof_area_sqft', 'current_phase', 'notes', 'roof_photo_url', 'eb_bill_url'];
  end if;
  if fu then
    allowed := allowed || array['status', 'sent_to_customer_at', 'accepted_by_name', 'accepted_via', 'accepted_note',
      'customer_response_at', 'lost_reason'];
  end if;
  if (to_jsonb(new) - allowed) is distinct from (to_jsonb(old) - allowed) then
    raise exception '%', case
      when visitor and fu then 'You can update the site visit and the follow-up of this quotation. Prices are changed by the person preparing it.'
      when visitor then 'You can update the site visit of this quotation. The quotation itself is prepared by someone else.'
      else 'You can follow up this quotation. Changes to it are made by the person preparing it.' end;
  end if;
  if new.status is distinct from old.status and not (
       (visitor and old.status in ('new', 'sales_review', 'site_details_pending', 'site_visit_scheduled')
                and new.status in ('site_visit_scheduled', 'site_visit_done'))
    or (fu and move in ('approved>sent_to_customer', 'sent_to_customer>customer_accepted', 'customer_accepted>advance_pending',
                        'sent_to_customer>cancelled', 'customer_accepted>cancelled', 'advance_pending>cancelled'))) then
    raise exception 'This step is done by the person preparing the quotation, the admin manager or the CEO.';
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_role_guard on quotation_requests;
create trigger trg_quotation_role_guard before update on quotation_requests
  for each row execute function quotation_role_guard();

-- Tell people when work is given to them, and pass the baton along the way
create or replace function quotation_assign_notify()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_link text := '/staff/quotations/' || new.id;
  v_who  text := coalesce(new.customer_name, 'customer') || ' · ' || coalesce(new.quotation_number, '')
                 || coalesce(' · ' || new.city, '') || coalesce(' · ' || new.mobile, '');
  v_by   text := coalesce(my_name(), 'The CEO');
  me     uuid := auth.uid();
  o      quotation_requests%rowtype;
begin
  if tg_op = 'UPDATE' then o := old; end if;
  if new.assigned_engineer_id is not null and new.assigned_engineer_id is distinct from o.assigned_engineer_id and new.assigned_engineer_id is distinct from me then
    insert into notifications (user_id, type, title, message, link) values (new.assigned_engineer_id, 'quotation',
      'Site visit given to you', v_who || coalesce(' · visit ' || to_char(new.site_visit_at at time zone 'Asia/Kolkata', 'DD Mon, HH12:MI AM'), '') || ' · by ' || v_by, v_link);
  end if;
  if new.assigned_sales_id is not null and new.assigned_sales_id is distinct from o.assigned_sales_id and new.assigned_sales_id is distinct from me then
    insert into notifications (user_id, type, title, message, link) values (new.assigned_sales_id, 'quotation',
      'Quotation to prepare', v_who || ' · by ' || v_by, v_link);
  end if;
  if new.follow_up_manager_id is not null and new.follow_up_manager_id is distinct from o.follow_up_manager_id and new.follow_up_manager_id is distinct from me then
    insert into notifications (user_id, type, title, message, link) values (new.follow_up_manager_id, 'quotation',
      'Customer follow-up given to you', v_who || ' · by ' || v_by, v_link);
  end if;
  if tg_op = 'UPDATE' then
    -- Visit date changed
    if new.site_visit_at is distinct from old.site_visit_at and new.site_visit_at is not null
       and new.assigned_engineer_id is not null and new.assigned_engineer_id is not distinct from old.assigned_engineer_id
       and new.assigned_engineer_id is distinct from me then
      insert into notifications (user_id, type, title, message, link) values (new.assigned_engineer_id, 'quotation',
        'Site visit date set', v_who || ' · ' || to_char(new.site_visit_at at time zone 'Asia/Kolkata', 'DD Mon, HH12:MI AM'), v_link);
    end if;
    -- Visit done → the preparer can start
    if new.site_visit_done_at is not null and old.site_visit_done_at is null
       and new.assigned_sales_id is not null and new.assigned_sales_id is distinct from me then
      insert into notifications (user_id, type, title, message, link) values (new.assigned_sales_id, 'quotation',
        'Site visit done — prepare the quotation', v_who, v_link);
    end if;
    -- Approved → the follow-up person can share it
    if new.status = 'approved' and old.status <> 'approved' and new.follow_up_manager_id is not null
       and new.follow_up_manager_id is distinct from new.assigned_sales_id then
      insert into notifications (user_id, type, title, message, link) values (new.follow_up_manager_id, 'quotation',
        'Quotation approved — ready to share with the customer', v_who, v_link);
    end if;
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_assign_notify on quotation_requests;
create trigger trg_quotation_assign_notify after insert or update on quotation_requests
  for each row execute function quotation_assign_notify();


-- ┌───────────────────────────────────────────────────────────────
-- │ lead_temperature_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Lead hot / cold v1 (26 Nov 2026)
--  * Hot / cold can be set at any stage, from the first enquiry (before only after sharing),
--    by the CEO, admin manager or any of the people working on the quotation.
--  * When it changes, the time and a short reason are kept; history shows who changed it.
--  * Logging a follow-up with hot / cold updates the quotation at any open stage.
-- Replaces quotation_guard() and follow_up_sync() from workflow_v2.sql. Safe to run more than once.

alter table quotation_requests add column if not exists lead_temperature_at   timestamptz;
alter table quotation_requests add column if not exists lead_temperature_note text;

create or replace function quotation_guard()
returns trigger language plpgsql set search_path = public as $$
declare
  v_uid   uuid := auth.uid();
  v_role  text;
  v_from  text := old.status;
  v_to    text := new.status;
  v_move  text := old.status || '>' || new.status;
  v_conv  boolean := coalesce(current_setting('greenergy.converting', true), '') = 'on';
begin
  -- Server-side service calls (public form, customer portal) and the SQL editor run without a user
  if v_uid is null then
    if v_to = 'customer_accepted' and v_from <> 'customer_accepted' and new.customer_response_at is null then
      new.customer_response_at := now();
    end if;
    return new;
  end if;

  v_role := my_role();
  if v_role is null then raise exception 'Your staff account is not active.'; end if;

  if v_from = 'project_created' and not v_conv then
    raise exception 'This quotation has a job card (%) and is locked.', old.job_number;
  end if;

  -- Job-card number and project link only come from convert_quotation_to_project()
  if not v_conv and (new.job_number is distinct from old.job_number or new.project_id is distinct from old.project_id
                     or new.converted_at is distinct from old.converted_at or new.converted_by is distinct from old.converted_by) then
    raise exception 'Job card numbers are issued only by "Create job card".';
  end if;
  if not v_conv and v_to = 'project_created' then
    raise exception 'Use "Create job card" to convert an accepted, hot quotation.';
  end if;

  -- Only managers reassign people
  if v_role = 'employee' and (new.assigned_sales_id is distinct from old.assigned_sales_id
       or new.assigned_engineer_id is distinct from old.assigned_engineer_id
       or new.follow_up_manager_id is distinct from old.follow_up_manager_id) then
    raise exception 'Only the CEO or admin manager can reassign a quotation.';
  end if;

  -- Stage moves
  if v_from <> v_to then
    if quotation_editable(v_from) and (quotation_editable(v_to) or v_to = 'owner_approval_pending') then
      null;                                                     -- prepare / submit for approval
    elsif v_from = 'owner_approval_pending' and v_to in ('approved','more_info_requested','rejected') then
      if v_role <> 'admin' then raise exception 'Only the CEO can approve, reject or send back a quotation.'; end if;
    elsif v_from = 'owner_approval_pending' and v_to = 'drafted' then
      null;                                                     -- withdrawn or sent back for changes
    elsif v_move in ('approved>sent_to_customer','sent_to_customer>customer_accepted','customer_accepted>advance_pending') then
      null;
    elsif v_from in ('approved','sent_to_customer','customer_accepted','advance_pending') and v_to = 'drafted' then
      -- Revision: approval is cleared and the old customer link stops working
      new.revision         := old.revision + 1;
      new.approved_by      := null;
      new.approved_by_name := null;
      new.approved_at      := null;
      new.portal_token     := uuid_generate_v4();
    elsif v_from in ('sent_to_customer','customer_accepted','advance_pending') and v_to = 'cancelled' then
      null;                                                     -- lost / declined
    elsif quotation_editable(v_from) and v_to in ('cancelled','rejected') then
      if v_role = 'employee' then raise exception 'Only the CEO or admin manager can close this quotation.'; end if;
    elsif v_from in ('cancelled','rejected') and v_to = 'drafted' then
      if v_role = 'employee' then raise exception 'Only the CEO or admin manager can reopen a quotation.'; end if;
    elsif v_to = 'project_created' and v_conv then
      null;
    else
      raise exception 'A quotation cannot move from "%" to "%".', v_from, v_to;
    end if;
  end if;

  -- Approval is stamped by the database, never by the client
  if v_to = 'approved' and v_from <> 'approved' then
    new.approved_by      := v_uid;
    new.approved_by_name := my_name();
    new.approved_at      := now();
    new.reviewed_by      := v_uid;
    new.reviewed_at      := now();
  elsif v_to = 'approved' and (new.approved_by is distinct from old.approved_by or new.approved_at is distinct from old.approved_at) then
    raise exception 'Approval details cannot be edited.';
  elsif v_to <> 'approved' and v_from = v_to and (new.approved_by is distinct from old.approved_by) then
    raise exception 'Approval details cannot be edited.';
  end if;

  -- Prices and scope change only while editable (a revision makes it editable again)
  if not (quotation_editable(v_to) or (quotation_editable(v_from) and v_to = 'owner_approval_pending')) and (
       new.admin_capacity_kw is distinct from old.admin_capacity_kw or new.admin_system_cost is distinct from old.admin_system_cost
    or new.admin_gst_amount  is distinct from old.admin_gst_amount  or new.admin_total_cost  is distinct from old.admin_total_cost
    or new.admin_subsidy     is distinct from old.admin_subsidy     or new.admin_net_cost    is distinct from old.admin_net_cost
    or new.central_subsidy   is distinct from old.central_subsidy   or new.state_subsidy     is distinct from old.state_subsidy
    or new.price_per_kw      is distinct from old.price_per_kw      or new.discount          is distinct from old.discount
    or new.region            is distinct from old.region            or new.panel_type        is distinct from old.panel_type
    or new.solar_type        is distinct from old.solar_type        or new.consumer_type     is distinct from old.consumer_type
    or new.valid_until       is distinct from old.valid_until) then
    raise exception 'Prices are locked after approval. Use "Revise" — the CEO must approve the new version.';
  end if;

  -- Hot / cold can be set at any stage (from the first enquiry), but not on a closed quotation
  if new.lead_temperature is distinct from old.lead_temperature
     and v_to in ('cancelled','rejected','project_created') and not v_conv then
    raise exception 'Hot / cold cannot be changed on a closed quotation.';
  end if;

  if v_to = 'sent_to_customer' and v_from <> 'sent_to_customer' then
    new.sent_to_customer_at := now();
    if new.next_follow_up_date is null or new.next_follow_up_date < current_date then
      new.next_follow_up_date := current_date + 1;
    end if;
  end if;
  if v_to = 'customer_accepted' and v_from <> 'customer_accepted' then
    new.customer_response_at := coalesce(new.customer_response_at, now());
    new.accepted_via := coalesce(new.accepted_via, 'staff');
  end if;
  return new;
end;$$;

create or replace function follow_up_sync()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update quotation_requests
     set next_follow_up_date = new.next_follow_up_date,
         follow_up_count     = follow_up_count + 1,
         lead_temperature    = coalesce(new.temperature, lead_temperature),
         lead_temperature_note = case when new.temperature is not null then left(new.notes, 300) else lead_temperature_note end
   where id = new.quotation_id and status not in ('project_created','cancelled','rejected');
  return new;
end;$$;

-- Stamp when the temperature changed (runs after the permission checks)
create or replace function quotation_temperature_stamp()
returns trigger language plpgsql as $$
begin
  if new.lead_temperature is distinct from old.lead_temperature then
    new.lead_temperature_at := case when new.lead_temperature is null then null else now() end;
  end if;
  return new;
end;$$;
drop trigger if exists trg_quotation_temp_stamp on quotation_requests;
create trigger trg_quotation_temp_stamp before update on quotation_requests
  for each row execute function quotation_temperature_stamp();


-- ┌───────────────────────────────────────────────────────────────
-- │ job_card_ongoing_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Job cards for ongoing projects v1 (26 Nov 2026)
-- Projects that started before the CRM (or were added without a quotation) can get a numbered
-- job card (GSS/JC/<FY>/<n>, same series as converted quotations), with:
--   * the cradle-to-grave milestones, those already finished marked done and the current one in progress;
--   * the payment schedule as an opening balance: amount already received (paid) + balance due;
--   * an optional old / paper job card reference.
-- Either for an existing project record, or a new ongoing project entered in one step.
-- CEO and admin manager only. Safe to run more than once.

alter table projects add column if not exists legacy_ref text;   -- old / paper job card number, if any
alter table projects add column if not exists onboarded_at timestamptz;  -- when an ongoing project got its CRM job card

-- The job number may only be set by the CRM's own functions
create or replace function project_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  if auth.uid() is null or coalesce(current_setting('greenergy.converting', true), '') = 'on' then return new; end if;
  if new.job_number is distinct from old.job_number or new.quotation_id is distinct from old.quotation_id then
    raise exception 'The job card number and quotation link cannot be changed.';
  end if;
  if new.admin_officer_id is distinct from old.admin_officer_id and not is_admin() then
    raise exception 'Only the CEO can appoint the administrative officer.';
  end if;
  return new;
end;$$;

-- p_project: an existing project without a job card, or null to create the project from p_details.
-- p_details (all optional except customer_name for a new project):
--   customer_name, customer_mobile, site_address, capacity_kwp, project_type, region, subsidy_job,
--   order_value, received, start_date (order date), target_commissioning, current_stage (stage_code),
--   admin_officer_id, legacy_ref, notes
create or replace function create_job_card_for_ongoing(p_project uuid, p_details jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  d        jsonb := coalesce(p_details, '{}'::jsonb);
  pr       projects%rowtype;
  v_job    text;
  v_start  date;
  v_sub    boolean;
  v_value  numeric;
  v_recv   numeric := greatest(coalesce(nullif(d->>'received', '')::numeric, 0), 0);
  v_cur    int;
  v_type   text;
  v_officer uuid := nullif(d->>'admin_officer_id', '')::uuid;
begin
  if not is_manager() then raise exception 'Only the CEO or admin manager can create a job card.'; end if;
  if v_officer is not null and not is_admin() then v_officer := null; end if;   -- only the CEO appoints officers
  v_type := case when d->>'project_type' in ('residential','commercial','industrial','street_light','solar_pump','hybrid') then d->>'project_type' end;

  if p_project is null then
    if coalesce(trim(d->>'customer_name'), '') = '' then raise exception 'Enter the customer name.'; end if;
    insert into projects (name, customer_name, customer_mobile, site_address, project_type, capacity_kwp, region,
                          subsidy_job, order_value, start_date, target_commissioning, status, notes, created_by)
    values (trim(d->>'customer_name') || coalesce(' - ' || nullif(d->>'capacity_kwp', '') || ' kW', ''),
            trim(d->>'customer_name'), nullif(trim(d->>'customer_mobile'), ''), nullif(trim(d->>'site_address'), ''),
            coalesce(v_type, 'residential'), nullif(d->>'capacity_kwp', '')::numeric,
            case when d->>'region' in ('puducherry','tamilnadu') then d->>'region' end,
            coalesce((d->>'subsidy_job')::boolean, false), nullif(d->>'order_value', '')::numeric,
            coalesce(nullif(d->>'start_date', '')::date, (now() at time zone 'Asia/Kolkata')::date),
            nullif(d->>'target_commissioning', '')::date, 'in_progress', nullif(trim(d->>'notes'), ''), auth.uid())
    returning * into pr;
  else
    select * into pr from projects where id = p_project for update;
    if not found then raise exception 'Project not found.'; end if;
    if pr.job_number is not null then raise exception 'This project already has job card %.', pr.job_number; end if;
    -- Fill in what the old record lacks
    update projects set
      customer_mobile      = coalesce(nullif(trim(d->>'customer_mobile'), ''), customer_mobile),
      site_address         = coalesce(nullif(trim(d->>'site_address'), ''), site_address),
      capacity_kwp         = coalesce(nullif(d->>'capacity_kwp', '')::numeric, capacity_kwp),
      project_type         = coalesce(v_type, project_type),
      region               = coalesce(case when d->>'region' in ('puducherry','tamilnadu') then d->>'region' end, region),
      subsidy_job          = coalesce((d->>'subsidy_job')::boolean, subsidy_job),
      order_value          = coalesce(nullif(d->>'order_value', '')::numeric, order_value),
      start_date           = coalesce(nullif(d->>'start_date', '')::date, start_date),
      target_commissioning = coalesce(nullif(d->>'target_commissioning', '')::date, target_commissioning)
    where id = pr.id returning * into pr;
  end if;

  v_start := coalesce(pr.start_date, (now() at time zone 'Asia/Kolkata')::date);
  v_sub   := pr.subsidy_job;
  v_value := coalesce(pr.order_value, 0);
  if v_recv > v_value and v_value > 0 then raise exception 'Amount received (%) is more than the order value (%).', v_recv, v_value; end if;

  v_job := next_doc_number('JC');
  perform set_config('greenergy.converting', 'on', true);
  update projects set job_number = v_job, onboarded_at = now(),
         legacy_ref = coalesce(nullif(trim(d->>'legacy_ref'), ''), legacy_ref),
         admin_officer_id = coalesce(v_officer, admin_officer_id),
         status = case when status = 'planning' and coalesce(d->>'current_stage', 'order_confirmed') <> 'order_confirmed' then 'in_progress' else status end
   where id = pr.id;
  perform set_config('greenergy.converting', 'off', true);

  -- Milestones: everything before the current stage is done, the current one is in progress
  if not exists (select 1 from project_stage_history where project_id = pr.id) then
    select t.sort_order into v_cur from project_stage_template() t where t.stage_code = coalesce(nullif(d->>'current_stage', ''), 'order_confirmed');
    v_cur := coalesce(v_cur, 1);
    insert into project_stage_history (project_id, stage_code, stage_name, phase, sort_order, is_subsidy, status, planned_date, notes)
    select pr.id, t.stage_code, t.stage_name, t.phase, t.sort_order, t.is_subsidy,
           case when t.is_subsidy and not v_sub then 'skipped'
                when t.sort_order < v_cur then 'completed'
                when t.sort_order = v_cur then 'in_progress'
                else 'pending' end,
           case when t.day_offset is null or (t.is_subsidy and not v_sub) then null else v_start + t.day_offset end,
           case when t.sort_order < v_cur and not (t.is_subsidy and not v_sub) then 'Done before the CRM job card' end
      from project_stage_template() t;
  end if;

  -- Payments as an opening balance
  if v_value > 0 and not exists (select 1 from project_payments where project_id = pr.id) then
    if v_recv > 0 then
      insert into project_payments (project_id, milestone_name, amount, status, paid_date, notes, created_by)
      values (pr.id, 'Received before the CRM job card', v_recv, 'paid', (now() at time zone 'Asia/Kolkata')::date, 'Opening balance', auth.uid());
    end if;
    if v_value - v_recv > 0 then
      insert into project_payments (project_id, milestone_name, amount, status, notes, created_by)
      values (pr.id, 'Balance due', v_value - v_recv, 'pending', 'Opening balance', auth.uid());
    end if;
  end if;

  insert into audit_log (action_by, action_type, target_entity, target_id, description)
  values (auth.uid(), 'job_card_ongoing', 'projects', pr.id,
          'Job card ' || v_job || ' created for ongoing project ' || coalesce(pr.customer_name, pr.name) || coalesce(' (old ref ' || nullif(trim(d->>'legacy_ref'), '') || ')', ''));
  if v_officer is not null and v_officer <> auth.uid() then
    insert into notifications (user_id, type, title, message, link)
    values (v_officer, 'project', 'You are the administrative officer for a job card', v_job || ' · ' || coalesce(pr.customer_name, pr.name), '/staff/projects/' || pr.id);
  end if;

  return jsonb_build_object('project_id', pr.id, 'job_number', v_job);
end;$$;
revoke all on function create_job_card_for_ongoing(uuid, jsonb) from public, anon;
grant execute on function create_job_card_for_ongoing(uuid, jsonb) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ project_delete_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Project delete v1 (26 Nov 2026)
--  * The CEO can delete a project that has NO numbered job card (wrong, test or duplicate entries).
--  * A project with a job card (GSS/JC/...) or linked to a quotation can never be deleted, by anyone.
--  * Team assignments, field job cards (and their logs, materials, expenses), milestones, payments and
--    documents of the project go with it; tasks and attendance are kept (their project link is cleared).
--  * A reason is required; a snapshot of the project and what was removed is kept in the audit log.
-- Safe to run more than once.

create or replace function project_delete_guard()
returns trigger language plpgsql set search_path = public as $$
begin
  if old.job_number is not null then
    raise exception 'Project % has job card % and cannot be deleted.', old.project_number, old.job_number;
  end if;
  if old.quotation_id is not null or exists (select 1 from quotation_requests where project_id = old.id) then
    raise exception 'Project % is linked to a quotation and cannot be deleted.', old.project_number;
  end if;
  if coalesce(current_setting('greenergy.deleting_project', true), '') <> old.id::text then
    raise exception 'Use "Delete project" (CEO) to delete a project.';
  end if;
  return old;
end;$$;
drop trigger if exists trg_project_delete_guard on projects;
create trigger trg_project_delete_guard before delete on projects
  for each row execute function project_delete_guard();

-- What would be removed (shown to the CEO before deleting)
create or replace function project_delete_preview(p_project uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare pr projects%rowtype;
begin
  if not is_admin() then raise exception 'Only the CEO can delete a project.'; end if;
  select * into pr from projects where id = p_project;
  if not found then raise exception 'Project not found.'; end if;
  return jsonb_build_object(
    'can_delete',  pr.job_number is null and pr.quotation_id is null and not exists (select 1 from quotation_requests where project_id = pr.id),
    'job_number',  pr.job_number,
    'team',        (select count(*) from project_employees where project_id = pr.id),
    'field_job_cards', (select count(*) from job_cards where project_id = pr.id),
    'field_entries', (select count(*) from job_card_materials m join job_cards j on j.id = m.job_card_id where j.project_id = pr.id)
                   + (select count(*) from job_card_logs l join job_cards j on j.id = l.job_card_id where j.project_id = pr.id),
    'milestones',  (select count(*) from project_stage_history where project_id = pr.id),
    'payments_paid', (select count(*) from project_payments where project_id = pr.id and status = 'paid'),
    'documents',   (select count(*) from project_documents where project_id = pr.id),
    'tasks',       (select count(*) from tasks where project_id = pr.id),
    'attendance_days', (select count(*) from attendance where project_id = pr.id));
end;$$;

create or replace function delete_project(p_project uuid, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
declare pr projects%rowtype; v_info jsonb;
begin
  if not is_admin() then raise exception 'Only the CEO can delete a project.'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Give a short reason for deleting.'; end if;
  select * into pr from projects where id = p_project for update;
  if not found then raise exception 'Project not found.'; end if;
  v_info := project_delete_preview(p_project);
  if not (v_info->>'can_delete')::boolean then
    raise exception 'Project % has a job card or a quotation and cannot be deleted.', pr.project_number;
  end if;

  insert into audit_log (action_by, action_type, target_entity, target_id, description, metadata)
  values (auth.uid(), 'project_deleted', 'projects', pr.id,
          'Project ' || pr.project_number || ' (' || coalesce(pr.customer_name, pr.name) || ') deleted: ' || trim(p_reason),
          jsonb_build_object('project', to_jsonb(pr), 'removed', v_info, 'reason', trim(p_reason),
                             'team', (select coalesce(jsonb_agg(to_jsonb(e)), '[]') from project_employees e where e.project_id = pr.id),
                             'field_job_cards', (select coalesce(jsonb_agg(to_jsonb(j)), '[]') from job_cards j where j.project_id = pr.id)));

  perform set_config('greenergy.deleting_project', pr.id::text, true);
  delete from projects where id = pr.id;
  perform set_config('greenergy.deleting_project', '', true);
end;$$;

revoke all on function project_delete_preview(uuid), delete_project(uuid, text) from public, anon;
grant execute on function project_delete_preview(uuid), delete_project(uuid, text) to authenticated;


-- ┌───────────────────────────────────────────────────────────────
-- │ task_delete_v1.sql
-- └───────────────────────────────────────────────────────────────

-- Task delete v1 (26 Nov 2026)
--  * The CEO can delete any task (wrong, duplicate or no longer needed). Nobody else can.
--  * A copy of the deleted task is kept in the audit log.
--  * If the task was still open and assigned to someone else, that person is told it was removed.
-- Nothing else in the database refers to tasks, so deleting one cannot break other records.
-- Safe to run more than once.

drop policy if exists "CEO delete tasks" on tasks;
create policy "CEO delete tasks" on tasks for delete using (is_admin());

create or replace function task_after_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into audit_log (action_by, action_type, target_entity, target_id, description, metadata)
  values (auth.uid(), 'task_deleted', 'tasks', old.id,
          'Task "' || left(old.title, 120) || '" deleted by ' || coalesce(my_name(), 'the server'),
          jsonb_build_object('task', to_jsonb(old)));
  if old.assigned_to is not null and old.assigned_to is distinct from auth.uid()
     and old.status not in ('completed', 'cancelled') then
    insert into notifications (user_id, type, title, message, link)
    values (old.assigned_to, 'task', 'A task given to you was removed',
            '"' || left(old.title, 120) || '" was deleted by ' || coalesce(my_name(), 'the CEO') || '. You do not need to do it.', '/staff/tasks');
  end if;
  return old;
end;$$;
drop trigger if exists trg_task_after_delete on tasks;
create trigger trg_task_after_delete after delete on tasks
  for each row execute function task_after_delete();
